export function RadialDemo({compact=false}:{compact?:boolean}){const [displayMode,setDisplayMode]=React.useState<'compact'|'full'>('compact');const [categoryId,setCategory]=React.useState('surface'),[activeParameterId,setParameter]=React.useState('coat'),[values,setValues]=React.useState(initialValues),[choiceId,setChoice]=React.useState('brushed'),[lastAction,setAction]=React.useState('Right-click or touch-hold the preview / hover to explore'),[open,setOpen]=React.useState(false),[anchor,setAnchor]=React.useState<{x:number;y:number}|null>(null);const [saved,setSaved]=React.useState<Record<string,number|string>|null>(null);const parameter=categories.flatMap(c=>c.controls).find(c=>c.id===activeParameterId);const props={categories,displayMode,categoryId,onCategoryChange:setCategory,values,onValueChange:(id:string,v:number|string)=>{setValues(old=>({...old,[id]:v}));setAction(`${id} → ${v}`)},activeParameterId,onActiveParameterChange:setParameter,choiceId,onChoiceChange:(id:string,value:string)=>{setChoice(id);setValues(v=>({...v,material:value}));setAction('Material selected / '+id)},onAction:(id:string)=>{if(id==='save'){setSaved({...values});setAction('Preset saved locally in demo state')}else if(id==='load'){if(saved){setValues(saved);setAction('Saved preset restored')}else setAction('No saved preset yet')}else{setAction(id.startsWith('add-')?'Create / '+id.slice(4)+' / demo intent':'Preset duplicated / demo intent')}},onAgentPrompt:(prompt:string)=>{setAction('Agent prompt queued for host review / '+prompt)},title:'Material radial inspector',breadcrumb:['Material',choiceId[0].toUpperCase()+choiceId.slice(1),'Solid']};
 return <div className={compact?'radial-lab radial-lab-compact':'radial-lab'}><div className="radial-lab-toolbar"><Badge>RIGHT-CLICK / TOUCH HOLD</Badge><div className="radial-display-options" role="group" aria-label="Inspector display size"><Button size="sm" variant={displayMode==='compact'?'silver':'ghost'} aria-pressed={displayMode==='compact'} onClick={()=>setDisplayMode('compact')}>Compact</Button><Button size="sm" variant={displayMode==='full'?'silver':'ghost'} aria-pressed={displayMode==='full'} onClick={()=>setDisplayMode('full')}>Full size</Button></div><Button size="sm" onClick={e=>{const r=e.currentTarget.getBoundingClientRect();setAnchor({x:r.left+r.width/2,y:r.bottom+280});setOpen(true)}}><SlidersHorizontal size={13}/>Open floating inspector</Button></div><div className="radial-lab-layout"><RadialInspectorContextMenu {...props} className="radial-lab-stage"><div className="radial-lab-scene"><div className="radial-material-object" style={{'--object-hue':values.hueA,'--object-coat':Number(values.coat)/100,'--object-color':values.material||'#b9c5d5'} as React.CSSProperties}/><span>DESIGN STUDY / MATERIAL</span></div><RadialInspector {...props} size={displayMode==='compact'?460:compact?570:730}/></RadialInspectorContextMenu><aside className="radial-lab-inspector"><span className="eyebrow">CENTRAL PARAMETER</span><h3>{parameter?.label}</h3><label className="nb-field"><span>Exact value</span><Input type="number" aria-label="Exact radial parameter value" min={parameter?.kind==='parameter'?parameter.min??0:0} max={parameter?.kind==='parameter'?parameter.max??100:100} step={parameter?.kind==='parameter'?parameter.step??1:1} value={Number(values[activeParameterId])} onChange={e=>{const n=e.currentTarget.valueAsNumber;if(Number.isFinite(n)){const min=parameter?.kind==='parameter'?parameter.min??0:0,max=parameter?.kind==='parameter'?parameter.max??100:100;props.onValueChange(activeParameterId,Math.max(min,Math.min(max,n)))}}}/></label><div className="radial-help"><span>01 / CONTEXT</span><p>Hover a section to expand its controls. On touch, tap the section.</p><span>02 / PRECISION</span><p>Drag any small dial directly, or use the central ring for precision. Drag up/right to increase; Shift makes finer pointer adjustments. Drag the central value for fine adjustment, or turn its outer ring. Back to sections returns to the first ring; nested Add menus keep their center Back. Arrow keys work on every dial.</p><span>03 / MATERIALS</span><p>Swatches change the live design study. Colour reveals a hue ring; Saved stores a local preset.</p></div><div className="radial-command-demo"><span className="eyebrow">LEGACY ACTION MENU</span><RadialMenu menuItems={commandItems} onSelect={item=>setAction('Command / '+item.label)}><span>Right-click here<br/><small>or focus and press Shift F10</small></span></RadialMenu></div></aside></div><div className="radial-lab-status" role="status"><span className="tiny-square"/>{lastAction}</div><RadialInspectorOverlay {...props} open={open} onOpenChange={setOpen} anchorPoint={anchor}/></div>;
}
export default function RadialPage(){const [theme,setTheme]=React.useState('dark');React.useEffect(()=>{document.documentElement.dataset.theme=theme},[theme]);return <MotionConfig reducedMotion="user"><TooltipProvider><div className="radial-page"><header className="catalog-topbar nb-glass"><a href="#/atelier"><Wordmark/></a><span className="catalog-topbar-label">UI SYSTEM / RADIAL INSPECTOR</span><Badge>0.3.3</Badge><div className="catalog-topbar-actions"><a className="nb-button button-outline button-sm" href="#/widgets">Widget atlas</a><Button size="icon" variant="ghost" aria-label="Toggle radial theme" onClick={()=>setTheme(t=>t==='dark'?'light':'dark')}>{theme==='dark'?<Sun size={15}/>:<Moon size={15}/>}</Button></div></header><main><div className="radial-page-heading"><a href="#/atelier" className="eyebrow">← COMPONENT ATELIER</a><h1>A circular <strong>command surface.</strong></h1><p>Categories, contextual controls, a precision dial and material choices — one focused instrument.</p></div><RadialDemo/></main></div></TooltipProvider></MotionConfig>}
